const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const money=n=>'₹'+new Intl.NumberFormat('en-IN').format(n);
const category=id=>CATEGORIES.find(c=>c.id===id);
const product=id=>PRODUCTS.find(p=>p.id===id);
const guide=p=>p.min===null?'Price on request':p.max===null?`${money(p.min)} onwards`:`${money(p.min)}–${new Intl.NumberFormat('en-IN').format(p.max)}`;
const cleanQuantity=value=>Math.min(10000,Math.max(1,Math.floor(Number(value)||1)));
let storageAvailable=true;
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem('inkbyte-v1-'+key))??fallback}catch{return fallback}}
function writeStore(key,value){try{localStorage.setItem('inkbyte-v1-'+key,JSON.stringify(value));return true}catch{storageAvailable=false;return false}}
