let cart=readStore('cart',[]);if(!Array.isArray(cart))cart=[];cart=cart.filter(x=>x&&product(x.id)&&typeof x.key==='string').map(x=>({...x,qty:cleanQuantity(x.qty),brand:String(x.brand||'').slice(0,30),size:String(x.size||''),color:/^#[0-9a-f]{6}$/i.test(x.color)?x.color:'#2c5d87',artworkName:String(x.artworkName||''),notes:String(x.notes||'').slice(0,2000)}));
