function collectionProducts(key){
 if(key==='new')return [
  ...PRODUCTS.filter(item=>item.isNew&&item.featured),
  ...PRODUCTS.filter(item=>item.isNew&&!item.featured),
 ];
 return PRODUCTS.filter(p=>key==='all'||!key||p.division===key||key==='wedding'&&p.category==='wedding-cards'||key==='apparel'&&['t-shirts','bags','eco-bags','hoodies'].includes(p.category)||key==='hampers'&&['corporate-hampers','festival-hampers'].includes(p.category))}
function route(){const raw=location.hash.slice(1)||'/';const [path,query='']=raw.split('?');return {path,params:new URLSearchParams(query)}}
function go(path){if(location.hash==='#'+path)render();else location.hash=path}
function shopUrl(collection='all',cat=''){return '/shop?'+new URLSearchParams({collection,...(cat?{category:cat}:{})})}
function toast(message,href='',label=''){clearTimeout(toastTimer);const el=$('#toast');el.innerHTML=`<span>${esc(message)}</span>${href?`<a href="#${esc(href)}">${esc(label)}</a>`:''}`;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),4500)}
function brand(){return `<a class="brand" href="#/" aria-label="Inkbyte home"><span class="brand-logo"><img src="assets/inkbyte-logo.png" alt="Inkbyte" width="760" height="205"></span></a>`}
function navLinks(){return [['All products',shopUrl()],['Corporate gifts',shopUrl('corporate')],['Print & stationery',shopUrl('printing')],['Clothing & bags',shopUrl('apparel')],['Wedding invitations',shopUrl('wedding')],['Gift hampers',shopUrl('hampers')]]}
