 $('#footer').innerHTML=`<footer class="site-footer"><div class="wrap"><div class="footer-main"><div class="footer-brand">${brand()}<p>Thoughtful products for the names, brands and moments that matter.</p><a class="link" href="#/about">A little about us ${icon('arrow')}</a></div><div class="footer-column"><strong>Find your thing</strong><a href="#${shopUrl('corporate')}">Corporate gifts</a><a href="#${shopUrl('printing')}">Print & stationery</a><a href="#${shopUrl('apparel')}">Clothing & bags</a><a href="#${shopUrl('wedding')}">Wedding invitations</a><a href="#${shopUrl('hampers')}">Gift hampers</a></div><div class="footer-column"><strong>Here to help</strong><a href="#/help">Frequently asked questions</a><a href="#/help?topic=artwork">Artwork & personalisation</a><a href="#/help?topic=delivery">Delivery & pricing</a><a href="#/contact">Contact us</a><a href="#/saved">Your saved products</a></div><div class="footer-column"><strong>Something in mind?</strong><a href="#/quote">Plan a bulk order ${icon('up')}</a><a href="#/contact">Start a conversation ${icon('up')}</a><a href="#/request">Your latest preview request</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} INKBYTE. Made for your ideas.</span><div class="footer-meta"><span>INR ₹</span><span>Illustrative product imagery</span><span class="preview-chip"><i></i> Design preview · Market guide pricing</span></div></div></div></footer>`;
 $('#drawer-backdrop').innerHTML=`<aside id="mobile-drawer" class="mobile-drawer" role="dialog" aria-modal="true" aria-label="Navigation" tabindex="-1"><div class="drawer-head">${brand()}<button class="icon-btn" data-action="close-menu" aria-label="Close menu">${icon('close')}</button></div>${searchForm()}<nav aria-label="Mobile navigation">${navLinks().map(([name,url])=>`<a href="#${url}">${name}${icon('chevron')}</a>`).join('')}<a href="#/quote">Get a bulk quote ${icon('up')}</a><a href="#/about">Our story ${icon('chevron')}</a><a href="#/contact">Contact us ${icon('chevron')}</a></nav><p class="muted">Print. Personalise. Gift. Make it yours.</p></aside>`;
