function updateCounters(){const count=cart.reduce((s,c)=>s+c.qty,0);for(const [selector,val] of [['.saved-counter',saved.length],['.cart-counter',count]]){$$(selector).forEach(el=>{el.textContent=val>99?'99+':val;el.classList.toggle('hidden',!val)})}}
function crumb(items){return `<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="#/">Home</a>${items.map(([name,url])=>`${icon('chevron')}${url?`<a href="#${esc(url)}">${esc(name)}</a>`:`<span aria-current="page">${esc(name)}</span>`}`).join('')}</nav>`}
function priceNote(){return `<div class="inline-note">${icon('info')}<span>Items marked “Price on request” need a quote. Market guide ranges are estimates and final prices depend on your requirements.</span></div>`}
function productImage(item, { eager = false } = {}) {
 const { sheet, index } = item.photo;
 const { src, columns, rows, width, height } = PHOTO_SHEETS[sheet];
 const column = index % columns;
 const row = Math.floor(index / columns);
 const aspect = (width * rows) / (height * columns);
 return `<span class="product-photo" role="img" aria-label="${esc(item.name)} concept photo"><span class="product-photo-frame" style="--photo-column:${column};--photo-row:${row};--photo-columns:${columns};--photo-rows:${rows};--photo-aspect:${aspect}"><img src="${esc(src)}" alt="" width="${width}" height="${height}" loading="${eager?'eager':'lazy'}" decoding="async"></span></span>`;
}
function productCard(p,index=0){return `<article class="product-card"><div class="product-media"><a href="#/product/${p.id}" aria-label="View ${esc(p.name)}">${productImage(p)}</a>${index===0?'<span class="product-tag">Make it yours</span>':''}<button class="save-btn ${saved.includes(p.id)?'selected':''}" data-action="save" data-id="${p.id}" aria-label="${saved.includes(p.id)?'Unsave':'Save'} ${esc(p.name)}" aria-pressed="${saved.includes(p.id)}">${icon('heart')}</button></div><div class="product-info"><div class="category-name">${esc(category(p.category).name)}</div><h3><a href="#/product/${p.id}">${esc(p.name)}</a></h3><div class="product-bottom"><div class="price-guide">${guide(p)}<small>${p.min===null?'Quote to your requirements':`Market guide / ${p.unit}`}</small></div><a class="product-arrow" href="#/product/${p.id}" aria-label="Customise ${esc(p.name)}">${icon('arrow')}</a></div></div></article>`}
function productsGrid(items){return `<div class="products-grid">${items.map((p,i)=>productCard(p,i)).join('')}</div>`}
function empty(title,text,cta='Explore the collection',url=shopUrl(),symbol='bag'){return `<div class="empty">${icon(symbol)}<h2>${title}</h2><p>${text}</p><a class="btn" href="#${url}">${cta}${icon('arrow')}</a></div>`}
